<script setup>
import { Head, Link, router } from '@inertiajs/vue3'; import AdminLayout from '@/Layouts/AdminLayout.vue';
defineProps({ rates: Object }); const format = (value) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value); const remove = (rate) => { if (confirm(`Arsipkan tarif ${rate.name}?`)) router.delete(route('admin.rates.destroy', rate.id)); };
</script>
<template><Head title="Tarif Keanggotaan"/><AdminLayout><div class="flex items-end justify-between"><div><p class="text-sm font-semibold text-aski-700">TARIF KEANGGOTAAN</p><h1 class="mt-1 text-3xl font-bold text-aski-900">Tarif Aktif dan Periode</h1></div><Link :href="route('admin.rates.create')" class="btn-primary">Tambah Tarif</Link></div><div class="card mt-7 overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-aski-50 text-aski-900"><tr><th class="p-4">Nama</th><th class="p-4">Tipe</th><th class="p-4">Nominal</th><th class="p-4">Periode aktif</th><th class="p-4"></th></tr></thead><tbody><tr v-for="rate in rates.data" :key="rate.id" class="border-t"><td class="p-4 font-semibold">{{ rate.name }}</td><td class="p-4">{{ rate.account_type === 'institution' ? 'Institusi' : 'Individu' }}</td><td class="p-4">{{ format(rate.amount) }}</td><td class="p-4">{{ rate.active_from }} — {{ rate.active_until || 'Tanpa batas' }}</td><td class="p-4 text-right"><Link :href="route('admin.rates.edit', rate.id)" class="font-semibold text-aski-700">Ubah</Link><button class="ml-3 text-red-600" @click="remove(rate)">Arsipkan</button></td></tr></tbody></table></div></AdminLayout></template>
